    private void checkSourceElements(Slice<Node> nodes)
    {
        if (!nodes.IsNil)
            foreach (var node in nodes)
            {
                if (isCanceled())
                    break;
                checkSourceElement(node);
            }
    }

    private void checkSourceElement(Node node)
