    private Type getTypeOfFuncClassEnumModule(Symbol symbol)
    {
        ref var links = ref valueSymbolLinks.Get(symbol);
        if (links.resolvedType == null)
            links.resolvedType = getTypeOfFuncClassEnumModuleWorker(symbol);
        return links.resolvedType;
    }

    private Type getTypeOfFuncClassEnumModuleWorker(Symbol symbol)
    {
        if ((((symbol.Flags & SymbolFlags.Module) != 0) && isShorthandAmbientModuleSymbol(symbol)))
        {
            return this.anyType;
        }
        else
        {
            if ((((((symbol.Flags & SymbolFlags.ValueModule) != 0) && (symbol.ValueDeclaration != null)) && Ast.IsSourceFile(symbol.ValueDeclaration)) && (symbol.ValueDeclaration.AsSourceFile().CommonJSModuleIndicator != null)))
            {
                var resolvedModule = this.resolveExternalModuleSymbol(symbol, false);
                if ((resolvedModule != symbol))
                {
                    return this.getTypeOfSymbol(resolvedModule);
                }
            }
        }
        var t = this.newObjectType(ObjectFlags.Anonymous, symbol);
        if (((symbol.Flags & SymbolFlags.Class) != 0))
        {
            var baseTypeVariable = this.getBaseTypeVariableOfClass(symbol);
            if ((baseTypeVariable != null))
            {
                return this.getIntersectionType((ReadOnlySpan<Type>)[t, baseTypeVariable]);
            }
            return t;
        }
        if ((this.strictNullChecks && ((symbol.Flags & SymbolFlags.Optional) != 0)))
        {
            return this.getOptionalType(t, true);
        }
        return t;
    }

    private Type getTypeOfVariableOrParameterOrProperty(Symbol symbol)
    {
        ref var links = ref valueSymbolLinks.Get(symbol);
        if (links.resolvedType == null)
        {
            var t = getTypeOfVariableOrParameterOrPropertyWorker(symbol);
            if (t == null)
                throw new InvalidOperationException("Unexpected nil type");
            // checker.go:16937–16944. Context-sensitive parameters may receive a
            // contextual type later; an earlier emit query must not cache the
            // provisional type before assignParameterType performs that work.
            if (links.resolvedType == null && !isParameterOfContextSensitiveSignature(symbol))
                links.resolvedType = t;
            return t;
        }

        return links.resolvedType;
    }

    private Type getTypeOfVariableOrParameterOrPropertyWorker(Symbol symbol)
    {
        if (((symbol.Flags & SymbolFlags.Prototype) != 0))
        {
            return this.getTypeOfPrototypeProperty(symbol);
        }
        if ((symbol == this.requireSymbol))
        {
            return this.anyType;
        }
        Debug.Assert((symbol.ValueDeclaration != null));
        var declaration = symbol.ValueDeclaration;
        if ((Ast.IsSourceFile(declaration) && Ast.IsJsonSourceFile(declaration.AsSourceFile())))
        {
            var statements = declaration.Statements();
            if ((GoRuntime.Len(statements) == 0))
            {
                return this.emptyObjectType;
            }
            return this.getWidenedType(this.getWidenedLiteralType(this.checkExpression(statements[0].Expression())));
        }
        if (!this.pushTypeResolution(symbol, TypeSystemPropertyName.Type))
        {
            return this.reportCircularityError(symbol);
        }
        if (((symbol.Flags & SymbolFlags.ModuleExports) != 0))
        {
            if ((symbol.NameValue.EqualsString("exports")))
            {
                return this.getTypeOfSymbol(this.resolveExternalModuleSymbol(symbol.ValueDeclaration.Symbol(), false));
            }
            return this.newAnonymousType(symbol, symbol.Members, default, default, default);
        }
        Type result = default;
        switch (declaration.Kind)
        {
            case Kind.Parameter:
            case Kind.PropertyDeclaration:
            case Kind.PropertySignature:
            case Kind.VariableDeclaration:
            case Kind.BindingElement:
            {
                result = this.getWidenedTypeForVariableLikeDeclaration(declaration, !this.isParameterOfContextSensitiveSignature(symbol));
                break;
            }
            case Kind.PropertyAssignment:
            {
                result = this.checkPropertyAssignment(declaration, CheckMode.Normal);
                break;
            }
            case Kind.ShorthandPropertyAssignment:
            {
                result = this.checkShorthandPropertyAssignment(declaration, true, CheckMode.Normal);
                break;
            }
            case Kind.MethodDeclaration:
            {
                result = this.checkObjectLiteralMethod(declaration, CheckMode.Normal);
                break;
            }
            case Kind.ExportAssignment:
            {
                if ((declaration.Type() != null))
                {
                    result = this.getTypeFromTypeNode(declaration.Type());
                }
                else
                {
                    result = this.widenTypeForVariableLikeDeclaration(this.checkExpressionCached(declaration.Expression()), declaration, false);
                }
                break;
            }
            case Kind.BinaryExpression:
            case Kind.CallExpression:
            {
                result = this.getWidenedTypeForAssignmentDeclaration(symbol);
                break;
            }
            case Kind.JsxAttribute:
            {
                result = this.checkJsxAttribute(declaration, CheckMode.Normal);
                break;
            }
            case Kind.EnumMember:
            {
                result = this.getTypeOfEnumMember(symbol);
                break;
            }
            default:
            {
                throw new InvalidOperationException(("Unhandled case in getTypeOfVariableOrParameterOrPropertyWorker: " + declaration.Kind.String()));
            }
        }
        if (!this.popTypeResolution())
        {
            return this.reportCircularityError(symbol);
        }
        return result;
    }

    // checker.go:19165. Symbols and semantic types share the original tagged stack.
    private bool pushTypeResolution(object target, TypeSystemPropertyName propertyName)
    {
        int cycleStart = findResolutionCycleStartIndex(target, propertyName);
        if (cycleStart >= 0)
        {
            for (int i = cycleStart; i < typeResolutions.Count; i++)
                typeResolutions.AsSpan()[i].result = false;
            return false;
        }

        typeResolutions = typeResolutions.Append(new TypeResolution { target = target, propertyName = propertyName, result = true });
        return true;
    }

    private bool popTypeResolution()
    {
        int last = typeResolutions.Count - 1;
        bool result = typeResolutions[last].result;
        typeResolutions[last] = default;
        typeResolutions = typeResolutions.Slice2(0, last);
        return result;
    }

    private int findResolutionCycleStartIndex(object target, TypeSystemPropertyName propertyName)
    {
        for (int i = typeResolutions.Count - 1; i >= resolutionStart; i--)
        {
            var r = typeResolutions[i];
            if (typeResolutionHasProperty(r))
                return -1;
            if (r.target == target && r.propertyName == propertyName)
                return i;
        }

        return -1;
    }

    private bool typeResolutionHasProperty(TypeResolution r)
    {
        return r.propertyName switch
        {
            TypeSystemPropertyName.InitializerIsUndefined => (nodeLinks.Get((Node)r.target).flags & NodeCheckFlags.InitializerIsUndefinedComputed) != 0,
            TypeSystemPropertyName.ResolvedReturnType => ((Signature)r.target).resolvedReturnType != null,
            TypeSystemPropertyName.Type => valueSymbolLinks.Get((Symbol)r.target).resolvedType != null,
            TypeSystemPropertyName.DeclaredType => typeAliasLinks.Get((Symbol)r.target).declaredType != null,
            TypeSystemPropertyName.ResolvedTypeArguments => ((Type)r.target).AsTypeReference().resolvedTypeArguments.IsNil == false,
            TypeSystemPropertyName.ResolvedBaseTypes => ((Type)r.target).AsInterfaceType().baseTypesResolved,
            TypeSystemPropertyName.ResolvedBaseConstructorType => ((Type)r.target).AsInterfaceType().resolvedBaseConstructorType != null,
            TypeSystemPropertyName.ResolvedBaseConstraint => ((Type)r.target).AsConstrainedType().resolvedBaseConstraint != null,
            TypeSystemPropertyName.WriteType => valueSymbolLinks.Get((Symbol)r.target).writeType != null,
            TypeSystemPropertyName.AliasTarget => aliasSymbolLinks.Get((Symbol)r.target).aliasTarget != null,
            _ => throw new InvalidOperationException("Unhandled case in typeResolutionHasProperty")
        };
    }

    private Type reportCircularityError(Symbol symbol)
    {
        var declaration = symbol.ValueDeclaration;
        if (declaration != null)
        {
            if (declaration.Type() != null)
            {
                error(declaration, Diagnostics.X_0_is_referenced_directly_or_indirectly_in_its_own_type_annotation, symbolToString(symbol));
                return errorType;
            }

            if (noImplicitAny && (!Ast.IsParameterDeclaration(declaration) || declaration.Initializer() != null))
                error(declaration, Diagnostics.X_0_implicitly_has_type_any_because_it_does_not_have_a_type_annotation_and_is_referenced_directly_or_indirectly_in_its_own_initializer, symbolToString(symbol));
        }
        else if ((symbol.Flags & SymbolFlags.Alias) != 0)
        {
            var node = getDeclarationOfAliasSymbol(symbol);
            if (node != null)
                error(node, Diagnostics.Circular_definition_of_import_alias_0, symbolToString(symbol));
        }
        return anyType;
    }

    private Type getWidenedTypeForVariableLikeDeclaration(Node declaration, bool reportErrors) => widenTypeForVariableLikeDeclaration(getTypeForVariableLikeDeclaration(declaration, true), declaration, reportErrors);
    internal Type getTypeForVariableLikeDeclaration(Node declaration, bool includeOptionality, CheckMode checkMode = CheckMode.Normal)
    {
        if (Ast.IsVariableDeclaration(declaration))
        {
            var grandParent = declaration.Parent.Parent;
            switch (grandParent.Kind)
            {
                case Kind.ForInStatement:
                    {
                        var indexType = getIndexType(getNonNullableTypeIfNeeded(checkExpressionEx(grandParent.Expression(), checkMode)));
                        return (indexType.flags & (TypeFlags.TypeParameter | TypeFlags.Index)) != 0
                            ? getExtractStringType(indexType)
                            : stringType;
                    }
                case Kind.ForOfStatement:
                    {
                        return this.checkRightHandSideOfForOf(grandParent);
                    }
            }
        }
        else
        {
            if (Ast.IsBindingElement(declaration))
            {
                return getTypeForBindingElement(declaration);
            }
        }
        var isProperty = ((Ast.IsPropertyDeclaration(declaration) && !Ast.HasAccessorModifier(declaration)) || Ast.IsPropertySignatureDeclaration(declaration));
        var isOptional = (includeOptionality && isOptionalDeclaration(declaration));
        var declaredType = this.tryGetTypeFromTypeNode(declaration);
        if (Ast.IsParameterDeclaration(declaration) && hasDotDotDotToken(declaration))
            validateCollectionsResolvedRestType(declaration, declaredType);
        if (Ast.IsCatchClauseVariableDeclarationOrBindingElement(declaration))
        {
            if ((declaredType != null))
            {
                if (((declaredType.flags & TypeFlags.AnyOrUnknown) != 0))
                {
                    return declaredType;
                }
                return this.errorType;
            }
            if (this.useUnknownInCatchVariables)
            {
                return this.unknownType;
            }
            else
            {
                return this.anyType;
            }
        }
        if ((declaredType != null))
        {
            return this.addOptionalityEx(declaredType, isProperty, isOptional);
        }
        if (((((this.noImplicitAny && Ast.IsVariableDeclaration(declaration)) && !Ast.IsBindingPattern(declaration.Name())) && ((this.getCombinedModifierFlagsCached(declaration) & ModifierFlags.Export) == 0)) && ((declaration.Flags & NodeFlags.Ambient) == 0)))
        {
            var initializer = declaration.Initializer();
            if ((((this.getCombinedNodeFlagsCached(declaration) & NodeFlags.Constant) == 0) && (((initializer == null) || this.isNullOrUndefined(initializer)))))
            {
                return this.autoType;
            }
            if (((initializer != null) && Ast.IsEmptyArrayLiteral(initializer)))
            {
                return this.autoArrayType;
            }
        }
        if (Ast.IsParameterDeclaration(declaration))
        {
            if ((declaration.Symbol() == null))
            {
                return null;
            }
            var fn = declaration.Parent;
            if ((Ast.IsSetAccessorDeclaration(fn) && this.hasBindableName(fn)))
            {
                var getter = Ast.GetDeclarationOfKind(this.getSymbolOfDeclaration(declaration.Parent), Kind.GetAccessor);
                if ((getter != null))
                {
                    var getterSignature = this.getSignatureFromDeclaration(getter);
                    var thisParameter = this.getAccessorThisParameter(fn);
                    if (((thisParameter != null) && (declaration == thisParameter)))
                    {
                        Debug.Assert((thisParameter.Type() == null));
                        return this.getTypeOfSymbol(getterSignature.thisParameter);
                    }
                    return this.getReturnTypeOfSignature(getterSignature);
                }
            }
            {
                var t = this.getParameterTypeOfFullSignature(fn, declaration);
                if ((t != null))
                {
                    return t;
                }
            }
            Type t2 = default;
            if ((declaration.Symbol().NameValue.EqualsString(Ast.InternalSymbolNameThis)))
            {
                t2 = this.getContextualThisParameterType(fn);
            }
            else
            {
                t2 = this.getContextuallyTypedParameterType(declaration);
            }
            if ((t2 != null))
            {
                return this.addOptionalityEx(t2, false, isOptional);
            }
        }
        if ((declaration.Initializer() != null))
        {
            var t3 = this.widenTypeInferredFromInitializer(declaration, this.checkDeclarationInitializer(declaration, checkMode, null));
            return this.addOptionalityEx(t3, isProperty, isOptional);
        }
        if ((this.noImplicitAny && Ast.IsPropertyDeclaration(declaration)))
        {
            if (!Ast.HasStaticModifier(declaration))
            {
                var constructor = Ast.FindConstructorDeclaration(declaration.Parent);
                Type t4 = default;
                switch (true)
                {
                    case true when (constructor != null):
                        {
                            t4 = this.getFlowTypeInConstructor(declaration.Symbol(), constructor);
                            break;
                        }
                    case true when ((declaration.ModifierFlags() & ModifierFlags.Ambient) != 0):
                        {
                            t4 = this.getTypeOfPropertyInBaseClass(declaration.Symbol());
                            break;
                        }
                }
                if ((t4 == null))
                {
                    return null;
                }
                return this.addOptionalityEx(t4, true, isOptional);
            }
            else
            {
                var staticBlocks = Core.Filter(declaration.Parent.Members(), Ast.IsClassStaticBlockDeclaration);
                Type t5 = default;
                switch (true)
                {
                    case true when (GoRuntime.Len(staticBlocks) != 0):
                        {
                            t5 = this.getFlowTypeInStaticBlocks(declaration.Symbol(), staticBlocks);
                            break;
                        }
                    case true when ((declaration.ModifierFlags() & ModifierFlags.Ambient) != 0):
                        {
                            t5 = this.getTypeOfPropertyInBaseClass(declaration.Symbol());
                            break;
                        }
                }
                if ((t5 == null))
                {
                    return null;
                }
                return this.addOptionalityEx(t5, true, isOptional);
            }
        }
        if (Ast.IsJsxAttribute(declaration))
        {
            return trueType;
        }
        if (Ast.IsBindingPattern(declaration.Name()))
        {
            return getTypeFromBindingPattern(declaration.Name(), false, true);
        }
        return null;
    }

    private Type tryGetTypeFromTypeNode(Node node) => node.Type() != null ? getTypeFromTypeNode(node.Type()) : null;
    private Type checkDeclarationInitializer(Node declaration, CheckMode checkMode, Type contextualType)
    {
        var initializer = declaration.Initializer();
        var t = this.getQuickTypeOfExpression(initializer);
        if ((t == null))
        {
            if ((contextualType != null))
            {
                t = this.checkExpressionWithContextualType(initializer, contextualType, null, checkMode);
            }
            else
            {
                t = this.checkExpressionCachedEx(initializer, checkMode);
            }
        }
        if (Ast.IsParameterDeclaration(Ast.GetRootDeclaration(declaration)))
        {
            var name = declaration.Name();
            switch (name.Kind)
            {
                case Kind.ObjectBindingPattern:
                {
                    if (isObjectLiteralType(t))
                    {
                        return this.padObjectLiteralType(t, name);
                    }
                    break;
                }
                case Kind.ArrayBindingPattern:
                {
                    if (isTupleType(t))
                    {
                        return this.padTupleType(t, name);
                    }
                    break;
                }
            }
        }
        return t;
    }

    private Type getQuickTypeOfExpression(Node node)
    {
        var expr = Ast.SkipParentheses(node);
        switch (true)
        {
            case true when Ast.IsAwaitExpression(expr):
                {
                    var t = getQuickTypeOfExpression(expr.Expression());
                    return t != null ? getAwaitedType(t) : null;
                }

            case true when ((((Ast.IsCallExpression(expr) && (expr.Expression().Kind != Kind.SuperKeyword)) && !Ast.IsRequireCall(expr, true)) && !this.isSymbolOrSymbolForCall(expr)) && !Ast.IsImportCall(expr)):
                {
                    if (isCallChain(expr))
                    {
                        return this.getReturnTypeOfSingleNonGenericSignatureOfCallChain(expr);
                    }

                    return this.getReturnTypeOfSingleNonGenericSignature(this.checkNonNullExpression(expr.Expression()), SignatureKind.Call);
                }

            case true when Ast.IsNewExpression(expr):
                {
                    return this.getReturnTypeOfSingleNonGenericSignature(this.checkNonNullExpression(expr.Expression()), SignatureKind.Construct);
                }

            case true when (Ast.IsAssertionExpression(expr) && !Ast.IsConstTypeReference(expr.Type())):
                {
                    return this.getTypeFromTypeNode(expr.Type());
                }

            case true when (Ast.IsLiteralExpression(node) || Ast.IsBooleanLiteral(node)):
                {
                    return this.checkExpression(node);
                }
        }

        return null;
    }

    private Type widenTypeInferredFromInitializer(Node declaration, Type t)
    {
        var widened = getWidenedLiteralTypeForInitializer(declaration, t);
        if (Ast.IsInJSFile(declaration))
        {
            if (isEmptyLiteralType(widened))
            {
                reportImplicitAny(declaration, anyType, WideningKind.Normal);
                return anyType;
            }
            if (isEmptyArrayLiteralType(widened))
            {
                reportImplicitAny(declaration, anyArrayType, WideningKind.Normal);
                return anyArrayType;
            }
        }
        return widened;
    }
    private Type getWidenedLiteralTypeForInitializer(Node declaration, Type t)
    {
        if ((getCombinedNodeFlagsCached(declaration) & NodeFlags.Constant) != 0 || isDeclarationReadonly(declaration))
            return t;
        return getWidenedLiteralType(t);
    }

    private Type widenTypeForVariableLikeDeclaration(Type t, Node declaration, bool reportErrors)
    {
        if ((t != null))
        {
            if ((((t.flags & TypeFlags.ESSymbol) != 0) && this.isGlobalSymbolConstructor(declaration.Parent)))
            {
                t = this.getESSymbolLikeTypeForNode(declaration);
            }

            if (reportErrors)
            {
                this.reportErrorsFromWidening(declaration, t, WideningKind.Normal);
            }

            if (((((t.flags & TypeFlags.UniqueESSymbol) != 0) && ((Ast.IsBindingElement(declaration) || (declaration.Type() == null)))) && (t.symbol != this.getSymbolOfDeclaration(declaration))))
            {
                t = this.esSymbolType;
            }

            return this.getWidenedType(t);
        }

        if ((Ast.IsParameterDeclaration(declaration) && (declaration.AsParameterDeclaration().DotDotDotToken != null)))
        {
            t = this.anyArrayType;
        }
        else
        {
            t = this.anyType;
        }

        if (reportErrors)
        {
            if (!declarationBelongsToPrivateAmbientMember(declaration))
            {
                this.reportImplicitAny(declaration, t, WideningKind.Normal);
            }
        }

        return t;
    }

    internal Type getWidenedType(Type t) => getWidenedTypeWithContext(t, null);
    private Type checkExpressionCached(Node node) => checkExpressionCachedEx(node, CheckMode.Normal);
    private Type checkExpressionCachedEx(Node node, CheckMode checkMode)
    {
        if (checkMode != CheckMode.Normal)
            return checkExpressionEx(node, checkMode);
        ref var links = ref typeNodeLinks.Get(node);
        // checker.go:7719. Cached checks temporarily isolate ongoing loop inference.
        if (links.resolvedType == null)
        {
            var savedFlowLoopStack = flowLoopStack;
            var savedFlowTypeCache = flowTypeCache;
            flowLoopStack = default;
            flowTypeCache = null;
            links.resolvedType = checkExpressionEx(node, checkMode);
            flowTypeCache = savedFlowTypeCache;
            flowLoopStack = savedFlowLoopStack;
        }

        return links.resolvedType;
    }

    internal Type checkExpression(Node node) => checkExpressionEx(node, CheckMode.Normal);
    private Type checkExpressionEx(Node node, CheckMode checkMode)
    {
        var saved = currentNode;
        currentNode = node;
        instantiationCount = 0;
        var uninstantiatedType = checkExpressionWorker(node, checkMode);
        var t = instantiateTypeWithSingleGenericCallSignature(node, uninstantiatedType, checkMode);
        if (isConstEnumObjectType(t))
            checkConstEnumAccess(node, t);
        currentNode = saved;
        return t;
    }

    private Type checkExpressionWorker(Node node, CheckMode checkMode)
    {
        switch (node.Kind)
        {
            case Kind.Identifier:
            {
                return this.checkIdentifier(node, checkMode);
            }
            case Kind.PrivateIdentifier:
            {
                return this.checkPrivateIdentifierExpression(node);
            }
            case Kind.ThisKeyword:
            {
                return this.checkThisExpression(node);
            }
            case Kind.SuperKeyword:
            {
                return this.checkSuperExpression(node);
            }
            case Kind.NullKeyword:
            {
                return this.nullWideningType;
            }
            case Kind.StringLiteral:
            case Kind.NoSubstitutionTemplateLiteral:
            {
                if (this.isSkipDirectInferenceNode(node))
                {
                    return this.blockedStringType;
                }
                return this.getFreshTypeOfLiteralType(this.getStringLiteralType(node));
            }
            case Kind.NumericLiteral:
            {
                this.checkGrammarNumericLiteral(node);
                return this.getFreshTypeOfLiteralType(this.getNumberLiteralType(JsNum.FromString(node.TextValue())));
            }
            case Kind.BigIntLiteral:
            {
                this.checkGrammarBigIntLiteral(node.AsBigIntLiteral());
                return this.getFreshTypeOfLiteralType(this.getBigIntLiteralType(JsNum.NewPseudoBigInt(JsNum.ParsePseudoBigInt(node.Text()), false)));
            }
            case Kind.TrueKeyword:
            {
                return this.trueType;
            }
            case Kind.FalseKeyword:
            {
                return this.falseType;
            }
            case Kind.TemplateExpression:
            {
                return this.checkTemplateExpression(node);
            }
            case Kind.RegularExpressionLiteral:
            {
                return this.checkRegularExpressionLiteral(node);
            }
            case Kind.ArrayLiteralExpression:
            {
                return this.checkArrayLiteral(node, checkMode);
            }
            case Kind.ObjectLiteralExpression:
            {
                return this.checkObjectLiteral(node, checkMode);
            }
            case Kind.PropertyAccessExpression:
            {
                return this.checkPropertyAccessExpression(node, checkMode, false);
            }
            case Kind.QualifiedName:
            {
                return this.checkQualifiedName(node, checkMode);
            }
            case Kind.ElementAccessExpression:
            {
                return this.checkIndexedAccess(node, checkMode);
            }
            case Kind.CallExpression:
            {
                if (Ast.IsImportCall(node))
                {
                    return this.checkImportCallExpression(node);
                }
                return this.checkCallExpression(node, checkMode);
            }
            case Kind.NewExpression:
            {
                return this.checkCallExpression(node, checkMode);
            }
            case Kind.TaggedTemplateExpression:
            {
                return this.checkTaggedTemplateExpression(node);
            }
            case Kind.ParenthesizedExpression:
            {
                return this.checkParenthesizedExpression(node, checkMode);
            }
            case Kind.ClassExpression:
            {
                return this.checkClassExpression(node);
            }
            case Kind.FunctionExpression:
            case Kind.ArrowFunction:
            {
                return this.checkFunctionExpressionOrObjectLiteralMethod(node, checkMode);
            }
            case Kind.TypeAssertionExpression:
            case Kind.AsExpression:
            {
                return this.checkAssertion(node, checkMode);
            }
            case Kind.TypeOfExpression:
            {
                return this.checkTypeOfExpression(node);
            }
            case Kind.NonNullExpression:
            {
                return this.checkNonNullAssertion(node);
            }
            case Kind.ExpressionWithTypeArguments:
            {
                return this.checkExpressionWithTypeArguments(node);
            }
            case Kind.SatisfiesExpression:
            {
                return this.checkSatisfiesExpression(node);
            }
            case Kind.MetaProperty:
            {
                return this.checkMetaProperty(node);
            }
            case Kind.DeleteExpression:
            {
                return this.checkDeleteExpression(node);
            }
            case Kind.VoidExpression:
            {
                return this.checkVoidExpression(node);
            }
            case Kind.AwaitExpression:
            {
                return this.checkAwaitExpression(node);
            }
            case Kind.PrefixUnaryExpression:
            {
                return this.checkPrefixUnaryExpression(node);
            }
            case Kind.PostfixUnaryExpression:
            {
                return this.checkPostfixUnaryExpression(node);
            }
            case Kind.BinaryExpression:
            {
                return this.checkBinaryExpression(node, checkMode);
            }
            case Kind.ConditionalExpression:
            {
                return this.checkConditionalExpression(node, checkMode);
            }
            case Kind.SpreadElement:
            {
                return this.checkSpreadExpression(node, checkMode);
            }
            case Kind.OmittedExpression:
            {
