                            return symbol;
                        }
                    }

                    return this.getPropertyOfObjectType(this.globalObjectType, name);
                }

            case true when ((t.flags & TypeFlags.Intersection) != 0):
                {
                    var prop = this.getPropertyOfUnionOrIntersectionType(t, name, true);
                    if ((prop != null))
