        return null;
    }

    private Type getTypeOfPropertyOfType(Type t, string name) =>
        getTypeOfPropertyOfType(t, ByteStringValue.FromString(name));

    private Type getTypeOfPropertyOfType(Type t, ByteStringValue name)
