        Normal = 0,
        Contextual = 1,
        Inferential = 2,
        SkipContextSensitive = 4,
        SkipGenericFunctions = 8,
        IsForSignatureHelp = 16,
        RestBindingElement = 32,
        TypeOnly = 64,
        ForceTuple = 128
    }

    private readonly Dictionary<Node, Type> contextFreeTypes = new(ReferenceEqualityComparer.Instance);
    private Type getContextFreeTypeOfExpression(Node node)
    {
        if (contextFreeTypes.TryGetValue(node, out var cached))
            return cached;
        pushContextualType(node, anyType, false);
        var t = checkExpressionEx(node, CheckMode.SkipContextSensitive);
        contextFreeTypes[node] = t;
        popContextualType();
        return t;
    }

    private void resolveUnionTypeMembers(Type t)
    {
        var calls = getUnionSignatures(Core.MapSlice(t.Types(), u => u == globalFunctionType ? Slice<Signature>.FromArray(new Signature[] { unknownSignature }) : getSignaturesOfType(u, SignatureKind.Call)));
        if (calls.Length == 0)
            calls = getArrayMemberCallSignatures(t);
        var constructs = getUnionSignatures(Core.MapSlice(t.Types(), u => getSignaturesOfType(u, SignatureKind.Construct)));
        setStructuredTypeMembers(t, null, calls, constructs, getUnionIndexInfos(t.Types()));
    }

    private Slice<Signature> getUnionSignatures(Slice<Slice<Signature>> signatureLists)
    {
        Slice<Signature> result = default;
        int indexWithLengthOverOne = default;
        int countLengthOverOne = default;
        {
            foreach (var i in GoRuntime.RangeKeys(signatureLists))
            {
                if ((GoRuntime.Len(signatureLists[i]) == 0))
                {
                    return default;
                }

                if ((GoRuntime.Len(signatureLists[i]) > 1))
                {
                    indexWithLengthOverOne = i;
                    countLengthOverOne++;
                }

                {
                    foreach (var signature in GoRuntime.RangeValues(signatureLists[i]))
                    {
                        if ((result.IsNil || (this.findMatchingSignature(result, signature, false, false, true) == null)))
                        {
                            var unionSignatures = this.findMatchingSignatures(signatureLists, signature, i);
                            if ((!unionSignatures.IsNil))
                            {
                                var s = signature;
                                if ((GoRuntime.Len(unionSignatures) > 1))
                                {
                                    var thisParameter = signature.thisParameter;
                                    var firstThisParameterOfUnionSignatures = Core.FirstNonNil(unionSignatures, (sig) =>
                                    {
                                        return sig.thisParameter;
                                    });
                                    if ((firstThisParameterOfUnionSignatures != null))
                                    {
                                        var thisType = this.getIntersectionType(Core.MapNonNilSlice(unionSignatures, (sig2) =>
                                        {
                                            if ((sig2.thisParameter != null))
                                            {
                                                return this.getTypeOfSymbol(sig2.thisParameter);
                                            }

                                            return null;
                                        }));
                                        thisParameter = this.createSymbolWithType(firstThisParameterOfUnionSignatures, thisType);
                                    }

                                    s = this.createUnionSignature(signature, unionSignatures);
                                    s.thisParameter = thisParameter;
                                }

                                result = GoRuntime.Append(result, s);
                            }
                        }
                    }
                }
            }
        }

        if (((GoRuntime.Len(result) == 0) && (countLengthOverOne <= 1)))
        {
            var masterList = signatureLists[indexWithLengthOverOne];
            Slice<Signature> results = GoSlices.Clone(masterList);
            {
                foreach (var range3 in GoRuntime.Range(signatureLists))
                {
                    var _2 = range3.Key;
                    var signatures = range3.Value;
                    if (!signatures.SameStorageRange(masterList))
                    {
                        var signature2 = signatures[0];
                        Debug.Assert((signature2 != null), "getUnionSignatures bails early on empty signature lists and should not have empty lists on second pass");
                        if (((GoRuntime.Len(signature2.typeParameters) != 0) && Core.Some(results, (s2) =>
                        {
                            return ((GoRuntime.Len(s2.typeParameters) != 0) && !this.compareTypeParametersIdentical(signature2.typeParameters, s2.typeParameters));
                        })))
                        {
                            results = default;
                        }
                        else
                        {
                            results = Core.MapSlice(results, (sig3) =>
                            {
                                return this.combineUnionOrIntersectionMemberSignatures(sig3, signature2, true);
                            });
                        }

                        if (results.IsNil)
                        {
                            break;
                        }
                    }
                }
            }

            result = results;
        }

        return result;
    }

    private Slice<Signature> getArrayMemberCallSignatures(Type t)
    {
        ByteStringValue memberName = default;
        {
            foreach (var range3 in GoRuntime.Range(t.Types()))
            {
                var i = range3.Key;
                var t2 = range3.Value;
                if ((((((t2.objectFlags & ObjectFlags.Instantiated) == 0) || (t2.symbol == null)) || (t2.symbol.Parent == null)) || !this.isArrayOrTupleSymbol(t2.symbol.Parent)))
                {
                    return default;
                }

                if ((i == 0))
                {
                    memberName = t2.symbol.NameValue;
                }
                else
                {
                    if ((!memberName.EqualsValue(t2.symbol.NameValue)))
                    {
                        return default;
                    }
                }
            }
        }

        var arrayArg = this.mapType(t, (t3) =>
        {
            return getMappedType(Core.IfElse(this.isReadonlyArraySymbol(t3.symbol.Parent), this.globalReadonlyArrayType, this.globalArrayType).AsInterfaceType().TypeParameters()[0], t3.Mapper());
        });
        var arrayType = this.createArrayTypeEx(arrayArg, someType(t, (t4) =>
        {
            return this.isReadonlyArraySymbol(t4.symbol.Parent);
        }));
        return this.getSignaturesOfType(this.getTypeOfPropertyOfType(arrayType, memberName), SignatureKind.Call);
    }

    private bool isArrayOrTupleSymbol(Symbol symbol)
    {
        if (symbol == null || globalArrayType.symbol == null || globalReadonlyArrayType.symbol == null)
            return false;
        return getSymbolIfSameReference(symbol, globalArrayType.symbol) != null || getSymbolIfSameReference(symbol, globalReadonlyArrayType.symbol) != null;
    }

    private Slice<IndexInfo> getUnionIndexInfos(Slice<Type> types)
    {
        var sourceInfos = getIndexInfosOfType(types[0]);
        Slice<IndexInfo> result = default;
        foreach (var info in sourceInfos)
            if (Core.Every(types, t => getIndexInfoOfType(t, info.keyType) != null))
            {
                var valueType = getUnionType(Core.MapSlice(types, t => getIndexTypeOfType(t, info.keyType)));
                result = GoRuntime.Append(result, newIndexInfo(info.keyType, valueType, Core.Some(types, t => getIndexInfoOfType(t, info.keyType).isReadonly), null, default));
            }

        return result;
    }

    private Type getIndexTypeOfType(Type t, Type keyType) => getIndexInfoOfType(t, keyType)?.valueType;
    private bool typeHasCallOrConstructSignatures(Type t) => (t.flags & TypeFlags.StructuredType) != 0 && (resolveStructuredTypeMembers(t).signatures.Length) != 0;
    private Slice<Symbol> getPropertiesOfUnionOrIntersectionType(Type t)
    {
        var d = t.AsUnionOrIntersectionType();
        if (d.resolvedProperties.IsNil)
        {
            var checkedNames = new HashSet<ByteStringKey>(ByteStringKey.Comparer);
            var props = Slice<Symbol>.Make(0);
            foreach (var current in d.types)
            {
                foreach (var prop in getPropertiesOfType(current))
                    if (checkedNames.Add(ByteStringKey.FromValue(prop.NameValue)))
                    {
                        var combined = getPropertyOfUnionOrIntersectionType(t, prop.NameValue, (t.flags & TypeFlags.Intersection) != 0);
                        if (combined != null)
                            props = props.Append(combined);
                    }

                if ((t.flags & TypeFlags.Union) != 0 && (getIndexInfosOfType(current).Length) == 0)
                    break;
            }

            d.resolvedProperties = props;
        }

        return d.resolvedProperties;
    }

    private Symbol getPropertyOfUnionOrIntersectionType(Type t, string name, bool skipObjectFunctionPropertyAugment) =>
        getPropertyOfUnionOrIntersectionType(t, ByteStringValue.FromString(name), skipObjectFunctionPropertyAugment);

    private Symbol getPropertyOfUnionOrIntersectionType(Type t, ByteStringValue name, bool skipObjectFunctionPropertyAugment)
    {
        var prop = getUnionOrIntersectionProperty(t, name, skipObjectFunctionPropertyAugment);
        return prop != null && (prop.CheckFlags & CheckFlags.ReadPartial) == 0 ? prop : null;
    }

    private Symbol getUnionOrIntersectionProperty(Type t, string name, bool skipObjectFunctionPropertyAugment) =>
        getUnionOrIntersectionProperty(t, ByteStringValue.FromString(name), skipObjectFunctionPropertyAugment);

    private Symbol getUnionOrIntersectionProperty(Type t, ByteStringValue name, bool skipObjectFunctionPropertyAugment)
    {
        var d = t.AsUnionOrIntersectionType();
        var cache = skipObjectFunctionPropertyAugment ? d.propertyCacheWithoutFunctionPropertyAugment ??= new SymbolTable() : d.propertyCache ??= new SymbolTable();
        var cached = cache[name];
        if (cached != null)
            return cached;
        var prop = createUnionOrIntersectionProperty(t, ref name, skipObjectFunctionPropertyAugment);
        if (prop != null)
        {
            cache[name] = prop;
            if (skipObjectFunctionPropertyAugment && (prop.CheckFlags & CheckFlags.Partial) == 0)
            {
                var augmented = d.propertyCache ??= new SymbolTable();
                if (augmented[name] == null)
                    augmented[name] = prop;
            }
        }

        return prop;
    }

    // checker.go:22104. Constituent symbols must share an actual declaration.
    private bool hasCommonDeclaration(Slice<Symbol> symbols)
    {
        var commonDeclarations = new HashSet<Node>(ReferenceEqualityComparer.Instance);
        foreach (var symbol in symbols)
        {
            if ((symbol.Declarations.Count) == 0)
                return false;
            if (commonDeclarations.Count == 0)
            {
                foreach (var declaration in symbol.Declarations)
                    commonDeclarations.Add(declaration);
                continue;
            }
            commonDeclarations.RemoveWhere(declaration => !GoSlices.Contains(symbol.Declarations, declaration));
            if (commonDeclarations.Count == 0)
                return false;
        }
        return commonDeclarations.Count != 0;
    }

    // The caller's private header may adopt the persistent key at symbol creation,
    // so both caches reuse that one string. No AST or source header is modified.
    private Symbol createUnionOrIntersectionProperty(Type containingType, ref ByteStringValue name, bool skipObjectFunctionPropertyAugment)
    {
        bool isUnion = (containingType.flags & TypeFlags.Union) != 0;
        bool mergedInstantiations = false;
        SymbolFlags propFlags = 0, optionalFlag = 0;
        Symbol singleProp = null;
        var propSet = Slice<Symbol>.Make(0);
        Slice<Type> indexTypes = default;
        CheckFlags checkFlags = isUnion ? 0 : CheckFlags.Readonly;
        optionalFlag = isUnion ? 0 : SymbolFlags.Optional;
        var syntheticFlag = CheckFlags.SyntheticMethod;
        foreach (var current in containingType.Types())
        {
            var t = getApparentType(current);
            if (isErrorType(t) || (t.flags & TypeFlags.Never) != 0)
                continue;
            var prop = getPropertyOfTypeEx(t, name, skipObjectFunctionPropertyAugment, false);
            if (prop != null)
            {
                var modifiers = getDeclarationModifierFlagsFromSymbol(prop);
                var writeModifiers = getDeclarationModifierFlagsFromSymbolEx(prop, true);
                if ((prop.Flags & SymbolFlags.ClassMember) != 0)
                {
                    if (isUnion)
                        optionalFlag |= prop.Flags & SymbolFlags.Optional;
                    else
                        optionalFlag &= prop.Flags;
                }

                if (singleProp == null)
                {
                    singleProp = prop;
                    propFlags = (prop.Flags & SymbolFlags.Accessor) != 0 ? prop.Flags & SymbolFlags.Accessor : SymbolFlags.Property;
                }
                else if (prop != singleProp)
                {
                    if (getTargetSymbol(prop) == getTargetSymbol(singleProp) && compareProperties(singleProp, prop, (a, b) => a == b ? Ternary.True : Ternary.False) == Ternary.True)
                        mergedInstantiations = singleProp.Parent != null && (getLocalTypeParametersOfClassOrInterfaceOrTypeAlias(singleProp.Parent).Length) != 0;
                    else
                    {
                        if (propSet.Count == 0)
                            propSet = propSet.Append(singleProp);
                        if (!GoSlices.Contains(propSet, prop))
                            propSet = propSet.Append(prop);
                    }

                    if ((propFlags & SymbolFlags.Accessor) != 0 && (prop.Flags & SymbolFlags.Accessor) != (propFlags & SymbolFlags.Accessor))
                        propFlags = propFlags & ~SymbolFlags.Accessor | SymbolFlags.Property;
                }

                if (isUnion && isReadonlySymbol(prop))
                    checkFlags |= CheckFlags.Readonly;
                else if (!isUnion && !isReadonlySymbol(prop))
                    checkFlags &= ~CheckFlags.Readonly;
                if ((modifiers & ModifierFlags.Protected) != 0 && (modifiers & ModifierFlags.Public) == 0)
                    checkFlags |= CheckFlags.ContainsProtected;
                else if ((modifiers & ModifierFlags.Private) != 0 && (modifiers & ModifierFlags.Public) == 0)
                    checkFlags |= CheckFlags.ContainsPrivate;
                else
                    checkFlags |= CheckFlags.ContainsPublic;
                if ((writeModifiers & ModifierFlags.Protected) != 0 && (writeModifiers & ModifierFlags.Public) == 0)
                    checkFlags |= CheckFlags.ContainsWriteProtected;
                else if ((writeModifiers & ModifierFlags.Private) != 0 && (writeModifiers & ModifierFlags.Public) == 0)
                    checkFlags |= CheckFlags.ContainsWritePrivate;
                else
                    checkFlags |= CheckFlags.ContainsWritePublic;
                if ((modifiers & ModifierFlags.Static) != 0)
                    checkFlags |= CheckFlags.ContainsStatic;
                if (!isPrototypeProperty(prop))
                    syntheticFlag = CheckFlags.SyntheticProperty;
            }
            else if (isUnion)
            {
                var indexInfo = !isLateBoundName(name) ? getApplicableIndexInfoForName(t, name) : null;
                if (indexInfo != null)
                {
                    propFlags = propFlags & ~SymbolFlags.Accessor | SymbolFlags.Property;
                    checkFlags |= CheckFlags.WritePartial | (indexInfo.isReadonly ? CheckFlags.Readonly : 0);
                    if (isTupleType(t))
                        indexTypes = indexTypes.Append(getRestTypeOfTupleType(t) ?? undefinedType);
                    else
                        indexTypes = indexTypes.Append(indexInfo.valueType);
                }
                else if ((t.objectFlags & ObjectFlags.ObjectLiteral) != 0 && (t.objectFlags & ObjectFlags.ContainsSpread) == 0)
                {
                    checkFlags |= CheckFlags.WritePartial;
                    indexTypes = indexTypes.Append(undefinedType);
                }
                else
                    checkFlags |= CheckFlags.ReadPartial;
            }
        }

        if (singleProp == null)
            return null;
        if (isUnion && (propSet.Count != 0 || (checkFlags & CheckFlags.Partial) != 0) &&
            (checkFlags & (CheckFlags.ContainsPrivate | CheckFlags.ContainsProtected | CheckFlags.ContainsWritePrivate | CheckFlags.ContainsWriteProtected)) != 0 &&
            !(propSet.Count != 0 && hasCommonDeclaration(propSet)))
        {
            if ((checkFlags & (CheckFlags.ContainsPrivate | CheckFlags.ContainsProtected)) != 0)
                return null;
            if ((checkFlags & CheckFlags.ContainsWritePrivate) != 0)
                checkFlags &= ~(CheckFlags.ContainsWritePublic | CheckFlags.ContainsWriteProtected);
            else if ((checkFlags & CheckFlags.ContainsWriteProtected) != 0)
                checkFlags &= ~CheckFlags.ContainsWritePublic;
        }
        if (propSet.Count == 0 && (checkFlags & CheckFlags.ReadPartial) == 0 && indexTypes.Length == 0)
        {
            if (!mergedInstantiations)
                return singleProp;
            Type singleType = null;
            TypeMapper singleMapper = null;
            if ((singleProp.Flags & SymbolFlags.Transient) != 0)
            {
                ref var singleLinks = ref valueSymbolLinks.Get(singleProp);
                singleType = singleLinks.resolvedType;
                singleMapper = singleLinks.mapper;
            }

            var clone = createSymbolWithType(singleProp, singleType);
            if (singleProp.ValueDeclaration != null)
                clone.Parent = singleProp.ValueDeclaration.Symbol().Parent;
            ref var cloneLinks = ref valueSymbolLinks.Get(clone);
            cloneLinks.containingType = containingType;
            cloneLinks.mapper = singleMapper;
            cloneLinks.writeType = getWriteTypeOfSymbol(singleProp);
            return clone;
        }

        if (propSet.Count == 0)
            propSet = propSet.Append(singleProp);
        Slice<Node> declarations = default;
        Type firstType = null, nameType = null;
        Slice<Type> propTypes = default;
        Slice<Type> writeTypes = default;
        Node firstValueDeclaration = null;
        bool hasNonUniformValueDeclaration = false;
        foreach (var prop in propSet)
        {
            if (firstValueDeclaration == null)
                firstValueDeclaration = prop.ValueDeclaration;
            else if (prop.ValueDeclaration != null && prop.ValueDeclaration != firstValueDeclaration)
                hasNonUniformValueDeclaration = true;
            foreach (var declaration in prop.Declarations)
                if (!GoSlices.Contains(declarations, declaration))
                    declarations = declarations.Append(declaration);
            var t = getTypeOfSymbol(prop);
            if (firstType == null)
            {
                firstType = t;
                nameType = valueSymbolLinks.Get(prop).nameType;
            }

            var writeType = getWriteTypeOfSymbol(prop);
            if (!writeTypes.IsNil || writeType != t)
            {
                if (writeTypes.IsNil)
                    writeTypes = GoSlices.Clone(propTypes);
                writeTypes = writeTypes.Append(writeType);
            }

            if (t != firstType)
                checkFlags |= CheckFlags.HasNonUniformType;
            if (isLiteralType(t) || isPatternLiteralType(t))
                checkFlags |= CheckFlags.HasLiteralType;
            if ((t.flags & TypeFlags.Never) != 0 && t != uniqueLiteralType)
                checkFlags |= CheckFlags.HasNeverType;
            propTypes = propTypes.Append(t);
        }

        propTypes = propTypes.Append(indexTypes);
        var result = newSymbolEx(propFlags | optionalFlag, name, checkFlags | syntheticFlag);
        result.Declarations = declarations;
        if (!hasNonUniformValueDeclaration && firstValueDeclaration != null)
        {
            result.ValueDeclaration = firstValueDeclaration;
            result.Parent = firstValueDeclaration.Symbol().Parent;
        }

        ref var links = ref valueSymbolLinks.Get(result);
        links.containingType = containingType;
        links.nameType = nameType;
        if (propTypes.Count > 2)
        {
            result.CheckFlags |= CheckFlags.DeferredType;
            ref var deferred = ref deferredSymbolLinks.Get(result);
            deferred.parent = containingType;
            deferred.constituents = propTypes;
            deferred.writeConstituents = writeTypes;
            return result;
        }

        links.resolvedType = isUnion ? getUnionType(propTypes) : getIntersectionType(propTypes);
        if (!writeTypes.IsNil)
            links.writeType = isUnion ? getUnionType(writeTypes) : getIntersectionType(writeTypes);
        return result;
    }

    private Type getTypeOfPropertyOrIndexSignatureOfType(Type t, string name) =>
        getTypeOfPropertyOrIndexSignatureOfType(t, ByteStringValue.FromString(name));

    private Type getTypeOfPropertyOrIndexSignatureOfType(Type t, ByteStringValue name)
    {
        var propertyType = getTypeOfPropertyOfType(t, name);
        if (propertyType != null)
            return propertyType;
        var indexInfo = getApplicableIndexInfoForName(t, name);
        if (indexInfo != null)
            return addOptionalityEx(indexInfo.valueType, true, true);
        return null;
    }

    private Type extractTypesOfKind(Type t, TypeFlags kind) => filterType(t, kind, static (constituent, flags) => (constituent.flags & flags) != 0);
    private string getPropertyNameFromIndex(Type indexType, Node accessNode) =>
        getPropertyNameValueFromIndex(indexType, accessNode).Materialize();
    private ByteStringValue getPropertyNameValueFromIndex(Type indexType, Node accessNode)
    {
        if (isTypeUsableAsPropertyName(indexType))
            return getPropertyNameValueFromType(indexType);
        if (accessNode != null && Ast.IsPropertyName(accessNode))
            return Ast.GetPropertyNameValueForPropertyNameNode(accessNode);
        return ByteStringValue.FromString(Ast.InternalSymbolNameMissing);
    }

    private Type getLiteralTypeFromProperty(Symbol prop, TypeFlags include, bool includeNonPublic)
    {
        if (includeNonPublic || (getDeclarationModifierFlagsFromSymbol(prop) & ModifierFlags.NonPublicAccessibilityModifier) == 0)
        {
            var t = valueSymbolLinks.Get(getLateBoundSymbol(prop)).nameType;
            if (t == null)
            {
                if (prop.NameValue.EqualsString(Ast.InternalSymbolNameDefault))
                    t = getStringLiteralType("default");
                else
                {
                    var name = Ast.GetNameOfDeclaration(prop.ValueDeclaration);
                    if (name != null)
                        t = getLiteralTypeFromPropertyName(name);
                    if (t == null && !IsKnownSymbol(prop))
                        t = getStringLiteralType(Ast.SymbolNameValue(prop));
                }
            }

            if (t != null && (t.flags & include) != 0)
                return t;
        }

        return neverType;
    }

    private Type getLiteralTypeFromPropertyName(Node name)
    {
        if (Ast.IsPrivateIdentifier(name))
        {
            return this.neverType;
        }
        if (Ast.IsNumericLiteral(name))
        {
            return this.getRegularTypeOfLiteralType(this.checkExpression(name));
        }
        if (Ast.IsComputedPropertyName(name))
        {
            return this.getRegularTypeOfLiteralType(this.checkComputedPropertyName(name));
        }
        var propertyName = Ast.GetPropertyNameValueForPropertyNameNode(name);
        if ((!propertyName.EqualsString(Ast.InternalSymbolNameMissing)))
        {
            return this.getStringLiteralType(propertyName);
        }
        if (Ast.IsExpression(name))
        {
            return this.getRegularTypeOfLiteralType(this.checkExpression(name));
        }
        return this.neverType;
    }

    private static IEnumerable<Type> getStringLiteralConstituentsForSuggestion(Slice<Type> types)
    {
        foreach (var type in types)
            if ((type.flags & TypeFlags.StringLiteral) != 0) yield return type;
    }

    private Type getSuggestedTypeForNonexistentStringLiteralType(Type source, Type target) => Core.GetSpellingSuggestionWithMaxCandidateCount(getStringLiteralValueText(source), getStringLiteralConstituentsForSuggestion(target.Types()), getStringLiteralValueText, CompareTypes, 1000);
}

public sealed partial class Checker
{
    private readonly record struct InstantiationExpressionKey(ulong nodeId, uint typeId);
    private readonly Dictionary<InstantiationExpressionKey, Type> instantiationExpressionTypes = new();

    private readonly record struct DiscriminatedContextualTypeKey(ulong nodeId, uint typeId);
    private readonly Dictionary<DiscriminatedContextualTypeKey, Type> discriminatedContextualTypes = new();
    private sealed class ObjectLiteralDiscriminator(Checker c, Slice<Node> props, Slice<Symbol> members) : Discriminator
    {
        public int len() => GoRuntime.Len(props) + GoRuntime.Len(members);
        public ByteStringValue name(int index) => index < GoRuntime.Len(props) ? props[index].Symbol().NameValue : members[index - GoRuntime.Len(props)].NameValue;
        public bool matches(int index, Type t)
        {
            Type propType;
            if (index < GoRuntime.Len(props))
            {
                var prop = props[index];
                if (Ast.IsPropertyAssignment(prop) || Ast.IsJsxAttribute(prop))
                    propType = prop.Initializer() != null ? c.getContextFreeTypeOfExpression(prop.Initializer()) : c.trueType;
                else
                    propType = c.getContextFreeTypeOfExpression(prop.Name());
            }
            else
                propType = c.undefinedType;
            foreach (var s in propType.Distributed())
                if (c.isTypeAssignableTo(s, t))
                    return true;
            return false;
        }
    }

    private Type discriminateContextualTypeByObjectMembers(Node node, Type contextualType)
    {
        var key = new DiscriminatedContextualTypeKey(Ast.GetNodeId(node), contextualType.id);
        if (discriminatedContextualTypes.TryGetValue(key, out var cached))
            return cached;
        var discriminated = getMatchingUnionConstituentForObjectLiteral(contextualType, node);
        if (discriminated == null)
        {
            var properties = Core.Filter(node.Properties(), (checker: this, contextualType), static (p, state) => p.Symbol() != null && (p.Kind == Kind.PropertyAssignment ? state.checker.isPossiblyDiscriminantValue(p.Initializer()) && state.checker.isDiscriminantProperty(state.contextualType, p.Symbol().NameValue) : p.Kind == Kind.ShorthandPropertyAssignment && state.checker.isDiscriminantProperty(state.contextualType, p.Symbol().NameValue)));
            var members = Core.Filter(getPropertiesOfType(contextualType), (checker: this, node, contextualType), static (s, state) => (s.Flags & SymbolFlags.Optional) != 0 && state.node.Symbol().Members?[s.NameValue] == null && state.checker.isDiscriminantProperty(state.contextualType, s.NameValue));
            discriminated = discriminateTypeByDiscriminableItems(contextualType, new ObjectLiteralDiscriminator(this, properties, members));
        }

        discriminatedContextualTypes[key] = discriminated;
        return discriminated;
    }

    private Type getMatchingUnionConstituentForObjectLiteral(Type unionType, Node node)
    {
        var keyPropertyName = getKeyPropertyName(unionType);
        if (keyPropertyName.Length != 0)
        {
            var property = Core.Find(node.Properties(), (checker: this, keyPropertyName), static (p, state) => p.Symbol() != null && p.Kind == Kind.PropertyAssignment && p.Symbol().NameValue.EqualsValue(state.keyPropertyName) && state.checker.isPossiblyDiscriminantValue(p.Initializer()));
            if (property != null)
                return getConstituentTypeForKeyType(unionType, getContextFreeTypeOfExpression(property.Initializer()));
        }

        return null;
    }

    private bool isPossiblyDiscriminantValue(Node node)
    {
        switch (node.Kind)
        {
            case Kind.StringLiteral:
            case Kind.NumericLiteral:
            case Kind.BigIntLiteral:
            case Kind.NoSubstitutionTemplateLiteral:
            case Kind.TemplateExpression:
            case Kind.TrueKeyword:
            case Kind.FalseKeyword:
            case Kind.NullKeyword:
            case Kind.Identifier:
            case Kind.UndefinedKeyword:
            {
                return true;
            }
            case Kind.PropertyAccessExpression:
            case Kind.ParenthesizedExpression:
            {
                return this.isPossiblyDiscriminantValue(node.Expression());
            }
            case Kind.JsxExpression:
            {
                return ((node.Expression() == null) || this.isPossiblyDiscriminantValue(node.Expression()));
            }
        }
        return false;
    }
}

public sealed partial class Checker
{
    private enum IntersectionFlags : uint
    {
        None = 0,
        NoSupertypeReduction = 1,
        NoConstraintReduction = 2
    }

    // checker.go:26590. Cache keys retain constituent order, flags and aliases.
    private readonly Dictionary<CacheHashKey, Type> intersectionTypes = new();
    internal Type getIntersectionType(List<Type> types) => getIntersectionTypeEx(types, IntersectionFlags.None, null);
    internal Type getIntersectionType(Slice<Type> types) => getIntersectionTypeEx(types.AsSpan(), IntersectionFlags.None, null);
    private Type getIntersectionType(ReadOnlySpan<Type> types) => getIntersectionTypeEx(types, IntersectionFlags.None, null);
    private Type getIntersectionTypeEx(Slice<Type> types, IntersectionFlags flags, TypeAlias alias) =>
