    private void checkTypeParameterListsIdentical(Symbol symbol)
    {
        if ((GoRuntime.Len(symbol.Declarations) == 1))
        {
            return;
        }

        ref var links = ref this.declaredTypeLinks.Get(symbol);
        if (!links.typeParametersChecked)
        {
            links.typeParametersChecked = true;
            var declarations = this.getClassOrInterfaceDeclarationsOfSymbol(symbol);
            if ((GoRuntime.Len(declarations) <= 1))
            {
                return;
            }

            var t = this.getDeclaredTypeOfSymbol(symbol);
            if (!this.areTypeParametersIdentical(declarations, t.AsInterfaceType().LocalTypeParameters(), (n) => n.TypeParameters()))
            {
                var name = this.symbolToString(symbol);
                {
                    foreach (var declaration in GoRuntime.RangeValues(declarations))
                    {
                        this.error(declaration.Name(), Diagnostics.All_declarations_of_0_must_have_identical_type_parameters, name);
                    }
                }
            }
        }
    }

    private bool areTypeParametersIdentical(Slice<Node> declarations, Slice<Type> targetParameters, Func<Node, Slice<Node>> getTypeParameterDeclarations)
    {
        var maxTypeArgumentCount = GoRuntime.Len(targetParameters);
        var minTypeArgumentCount = this.getMinTypeArgumentCount(targetParameters);
        {
            foreach (var declaration in GoRuntime.RangeValues(declarations))
            {
                var sourceParameters = getTypeParameterDeclarations(declaration);
                if (((GoRuntime.Len(sourceParameters) < minTypeArgumentCount) || (GoRuntime.Len(sourceParameters) > maxTypeArgumentCount)))
                {
                    return false;
                }

                {
                    foreach (var range3 in GoRuntime.Range(sourceParameters))
                    {
                        var i = range3.Key;
                        var source = range3.Value;
                        var target = targetParameters[i];
                        if ((!source.Name().TextValue().EqualsString(target.symbol.Name)))
                        {
                            return false;
                        }

                        var constraintNode = source.AsTypeParameterDeclaration().Constraint;
                        var targetConstraint = this.getConstraintOfTypeParameter(target);
                        if ((((constraintNode != null) && (targetConstraint != null)) && !this.isTypeIdenticalTo(this.getTypeFromTypeNode(constraintNode), targetConstraint)))
                        {
                            return false;
                        }

                        var defaultNode = source.AsTypeParameterDeclaration().DefaultType;
                        var targetDefault = this.getDefaultFromTypeParameter(target);
                        if ((((defaultNode != null) && (targetDefault != null)) && !this.isTypeIdenticalTo(this.getTypeFromTypeNode(defaultNode), targetDefault)))
                        {
                            return false;
                        }
                    }
                }
            }
        }

        return true;
    }

    private sealed record InheritanceInfo(Symbol prop, Type containingType);
    private bool checkInheritedPropertiesAreIdentical(Type t, Node node)
    {
        var bases = getBaseTypes(t);
        if ((bases.Length) < 2)
            return true;
        var seen = new Dictionary<ByteStringKey, InheritanceInfo>(ByteStringKey.Comparer);
        foreach (var (name, property) in resolveDeclaredMembers(t).declaredMembers ?? new SymbolTable())
            if (isNamedMember(property, name))
                seen[ByteStringKey.FromValue(property.NameValue)] = new(property, t);
        bool identical = true;
        foreach (var @base in bases)
            foreach (var property in getPropertiesOfType(getTypeWithThisArgument(@base, t.AsInterfaceType().thisType, false)))
            {
                if (!property.NameValue.TryGetValue(seen, out var existing))
                    seen[ByteStringKey.FromValue(property.NameValue)] = new(property, @base);
                else if (existing.containingType != t && !isPropertyIdenticalTo(existing.prop, property))
                {
                    identical = false;
                    var name1 = typeToStringByteString(existing.containingType);
                    var name2 = typeToStringByteString(@base);
                    var info = NewDiagnosticForNode(node, Diagnostics.Named_property_0_of_types_1_and_2_are_not_identical, symbolToString(property), name1, name2);
                    addDiagnostic(Ast.NewDiagnosticChain(info, Diagnostics.Interface_0_cannot_simultaneously_extend_types_1_and_2, typeToStringByteString(t), name1, name2));
                }
            }

        return identical;
    }

    private bool isPropertyIdenticalTo(Symbol source, Symbol target) => compareProperties(source, target, compareTypesIdentical) != Ternary.False;
    private void checkClassOrInterfaceForDuplicateIndexSignatures(Node node)
    {
        ref var links = ref declaredTypeLinks.Get(getSymbolOfDeclaration(node));
        if (!links.indexSignaturesChecked)
        {
            links.indexSignaturesChecked = true;
            checkTypeForDuplicateIndexSignatures(node);
        }
    }

    private void checkUnionOrIntersectionType(Node node)
    {
        node.ForEachChild(child =>
        {
            checkSourceElement(child);
            return false;
        });
        getTypeFromTypeNode(node);
    }

    private Type getTypeFromUnionTypeNode(Node node)
    {
        ref var links = ref typeNodeLinks.Get(node);
        return links.resolvedType ??= getUnionTypeEx(Core.MapSlice(node.AsUnionTypeNode().Types.Nodes, getTypeFromTypeNode), UnionReduction.Literal, getAliasForTypeNode(node), null);
    }

    private Type getTypeFromIntersectionTypeNode(Node node)
    {
        ref var links = ref typeNodeLinks.Get(node);
        if (links.resolvedType == null)
        {
            var alias = getAliasForTypeNode(node);
            var types = Core.MapSlice(node.AsIntersectionTypeNode().Types.Nodes, getTypeFromTypeNode);
            var noSupertypeReduction = false;
            if (types.Count == 2)
            {
                var emptyIndex = GoSlices.Index(types, emptyTypeLiteralType);
                if (emptyIndex >= 0)
                {
                    var t = types[1 - emptyIndex];
                    noSupertypeReduction = (t.flags & (TypeFlags.String | TypeFlags.Number | TypeFlags.BigInt)) != 0
                        || (t.flags & TypeFlags.TemplateLiteral) != 0 && isPatternLiteralType(t);
                }
            }
            links.resolvedType = getIntersectionTypeEx(types, noSupertypeReduction ? IntersectionFlags.NoSupertypeReduction : IntersectionFlags.None, alias);
        }

        return links.resolvedType;
    }
}

