                            var tpDeclaration = tp.symbol.Declarations[0];
                            Node tpScope = default;
                            switch (true)
                            {
                                case true when Ast.IsTypeParameterDeclaration(tpDeclaration):
                                    {
                                        tpScope = tpDeclaration.Parent;
                                        break;
                                    }

                                case true when tp.AsTypeParameter().isThisType:
                                    {
